import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])

    if n == 0:
        print(-1)
        return

    values = list(map(int, data[1:n+1]))

    def insert_node(root, val):
        if root is None:
            return {'val': val, 'left': None, 'right': None}

        if val < root['val']:
            root['left'] = insert_node(root['left'], val)
        else:
            root['right'] = insert_node(root['right'], val)

        return root

    root = None
    for val in values:
        root = insert_node(root, val)

    def find_min(node):
        if node is None:
            return None
        current = node
        while current and current['left'] is not None:
            current = current['left']
        return current['val'] if current else None

    min_val = find_min(root)
    if min_val is None:
        print(-1)
    else:
        print(min_val)

if __name__ == "__main__":
    main()
